            C++

    #include <iostream>
#include <vector>
using namespace std;

// A XOR based function to find
// the element that appears only once
int single(vector<int>& arr) {

    int XOR = 0;
    for (int i = 0; i < arr.size(); i++) {
        XOR ^= arr[i];
    }
    return XOR;
}

int main()
{
    vector<int> arr = { 1, 1, 2, 2, 3, 4, 4};
    cout << single(arr) << "\n";
    return 0;
}


